&lt;/section&gt;

&lt;style&gt;
[HANDLE_001] url('[URL_004]');

.pricing-section{
padding:80px 20px;
background:transparent;
}

.pricing-header{
text-align:center;
margin-bottom:50px;
}

.pricing-header h2{
font-family:'Oswald', sans-serif;
font-size:64px;
color:#111;
margin-bottom:15px;
}

.pricing-header p{
font-family:'Montserrat', sans-serif;
font-size:20px;
color:#555;
max-width:700px;
margin:auto;
line-height:1.6;
}

.pricing-grid{
max-width:1300px;
margin:auto;
display:grid;
grid-template-columns:repeat(3, 1fr);
gap:30px;
}

.pricing-card{
background:#fff;
border:2px solid #e5e5e5;
padding:40px 35px;
text-align:center;
border-radius:16px;
box-shadow:0 8px 30px rgba(0,0,0,0.06);
transition:0.3s ease;
}

.pricing-card:hover{
transform:translateY(-6px);
}

.featured{
border:3px solid #ff6a00;
transform:scale(1.03);
}

.pricing-note{
background:#fff3eb;
color:#ff6a00;
font-family:'Montserrat', sans-serif;
font-size:14px;
font-weight:700;
padding:10px 14px;
border-radius:100px;
display:inline-block;
margin-bottom:25px;
}

.pricing-card h3{
font-family:'Oswald', sans-serif;
font-size:42px;
color:#111;
margin-bottom:15px;
}

.price{
font-family:'Montserrat', sans-serif;
font-size:72px;
font-weight:800;
color:#111;
margin-bottom:30px;
}

.pricing-card ul{
list-style:none;
padding:0;
margin:0 0 35px;
text-align:left;
}

.pricing-card li{
font-family:'Montserrat', sans-serif;
font-size:17px;
color:#444;
margin-bottom:14px;
position:relative;
padding-left:28px;
line-height:1.5;
}

.pricing-card li::before{
content:"✓";
position:absolute;
left:0;
color:#58c11b;
font-weight:800;
}

.pricing-btn{
display:inline-block;
background:#58c11b;
color:#fff;
text-decoration:none;
font-family:'Montserrat', sans-serif;
font-size:17px;
font-weight:700;
padding:18px 34px;
border-radius:10px;
transition:0.3s ease;
}

.pricing-btn:hover{
opacity:0.9;
color:#fff;
}

[HANDLE_002](max-width:991px){

.pricing-grid{
grid-template-columns:1fr;
}

.featured{
transform:none;
}

.pricing-header h2{
font-size:42px;
}

.price{
font-size:54px;
}

}
&lt;/style&gt;
